'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    FileText,
    TrendingUp,
    Download,
    Award,
    ChevronDown,
    Loader2,
    Activity,
    Star
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { gradesService } from '@/lib/services/grades';
import { attendanceService } from '@/lib/services/attendance';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function RiwayatNilaiPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [studentInfo, setStudentInfo] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [reports, setReports] = useState<any[]>([]);
    const [summary, setSummary] = useState({
        gpa: 0,
        trend: 0,
        totalHafalan: 0,
        attendance: 100
    });

    const fetchData = useCallback(async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;
            setStudentInfo(student);

            const gradesData = await gradesService.getByStudent(student.id);

            const grouped = gradesData.reduce((acc: any, grade: any) => {
                const key = `${grade.academic_year_id || '2024'}-${grade.semester}`;
                if (!acc[key]) {
                    acc[key] = {
                        semester: `Semester ${grade.semester === 1 ? 'Ganjil' : 'Genap'} ${grade.academic_year_id || ''}`,
                        grades: []
                    };
                }
                acc[key].grades.push({
                    no: acc[key].grades.length + 1,
                    name: grade.subject?.name || 'Unknown',
                    kkm: 75,
                    score: grade.final_grade || 0,
                    letter: gradesService.getGradeLetter(grade.final_grade || 0),
                    predicate: getPredicate(grade.final_grade || 0)
                });
                return acc;
            }, {});

            const reportsArray = Object.values(grouped).map((group: any) => {
                const avg = group.grades.length > 0
                    ? group.grades.reduce((sum: number, g: any) => sum + (g.score || 0), 0) / group.grades.length
                    : 0;
                return {
                    ...group,
                    gpa: (avg / 25).toFixed(2)
                };
            });

            setReports(reportsArray);

            const [gpaH, hafalan, attPercentage] = await Promise.all([
                studentDashboardService.getGPAHistory(student.id),
                studentDashboardService.getHafalanData(student.id),
                attendanceService.getStudentAttendanceSummary(student.id)
            ]);

            const currentGPA = reportsArray.length > 0 ? Number(reportsArray[0].gpa) : 0;
            const prevGPA = gpaH.length > 1 ? gpaH[gpaH.length - 2].gpa : currentGPA;

            setSummary({
                gpa: currentGPA,
                trend: currentGPA - prevGPA,
                totalHafalan: hafalan?.completed || 0,
                attendance: attPercentage
            });
        } catch (err) {
            console.error('Error fetching grades history:', err);
        } finally {
            setIsLoading(false);
        }
    }, []);

    const getPredicate = (score: number) => {
        if (score >= 90) return 'Sangat Baik';
        if (score >= 80) return 'Baik';
        if (score >= 70) return 'Cukup';
        return 'Kurang';
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && reports.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyusun Lapor Akademik...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Academic Transcript
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Riwayat <span className="text-indigo-500">Nilai & Rapor</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Buku laporan pencapaian akademik digital yang terdokumentasi rapi.</p>
                        </div>
                        <div className="flex gap-4">
                            <button className="px-6 py-3.5 bg-neutral-900 border border-neutral-800 rounded-2xl text-[10px] font-black text-white hover:bg-neutral-800 transition-all flex items-center gap-3 uppercase tracking-widest shadow-xl">
                                <Download className="w-4 h-4 text-indigo-500" />
                                Export Rapor PDF
                            </button>
                        </div>
                    </div>

                    {/* Stats Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-900 p-8 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-500/10 relative overflow-hidden group">
                            <div className="relative z-10">
                                <p className="text-indigo-100/60 text-[10px] font-black uppercase tracking-widest mb-4">IPK Terakhir</p>
                                <h4 className="text-6xl font-black tracking-tighter">{summary.gpa || '0.00'}</h4>
                                <div className={`mt-6 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-white/10 w-fit px-4 py-2 rounded-xl backdrop-blur-md border border-white/5`}>
                                    <TrendingUp className={`w-3.5 h-3.5 ${summary.trend >= 0 ? 'text-emerald-400' : 'text-rose-400'}`} />
                                    {summary.trend >= 0 ? 'Meningkat' : 'Menurun'} {Math.abs(summary.trend).toFixed(2)}
                                </div>
                            </div>
                            <Award className="absolute top-1/2 right-0 -translate-y-1/2 w-40 h-40 text-white/10 rotate-12 group-hover:rotate-0 transition-transform duration-1000" />
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Star className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Progres Tahfidz</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.totalHafalan} <span className="text-lg text-neutral-600 font-bold uppercase ml-1">/ 30 Juz</span></h4>
                            <div className="w-full h-1.5 bg-neutral-900 rounded-full mt-6 overflow-hidden border border-neutral-800">
                                <div className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)] transition-all duration-1000" style={{ width: `${(summary.totalHafalan / 30) * 100}%` }}></div>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Activity className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Absensi Kehadiran</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.attendance}%</h4>
                            <div className="mt-4 flex items-center gap-2">
                                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Kualifikasi Sangat Baik</span>
                            </div>
                        </div>
                    </div>

                    {/* Reports List */}
                    <div className="space-y-10">
                        {reports.length === 0 ? (
                            <div className="bg-[#0a0a0a] p-24 rounded-[3rem] border border-neutral-800/50 text-center shadow-2xl">
                                <div className="w-20 h-20 bg-neutral-900 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-neutral-800">
                                    <FileText className="w-10 h-10 text-neutral-800" />
                                </div>
                                <h3 className="text-2xl font-black text-white mb-2 tracking-tight">Belum Ada Transkip</h3>
                                <p className="text-neutral-500 max-w-sm mx-auto font-medium">Laporan akademik anda akan muncul di sini setelah divalidasi oleh asatidzah.</p>
                            </div>
                        ) : (
                            reports.map((report, idx) => (
                                <div key={idx} className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                                    <div className="p-8 border-b border-neutral-800/50 bg-neutral-900/20 flex items-center justify-between">
                                        <div>
                                            <h3 className="font-black text-white uppercase tracking-[0.2em] text-sm">{report.semester}</h3>
                                            <div className="flex items-center gap-2 mt-1">
                                                <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                                                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Cumulative GPA: {report.gpa}</p>
                                            </div>
                                        </div>
                                        <button className="p-2.5 bg-[#050505] text-neutral-600 hover:text-white rounded-xl border border-neutral-800 transition-all">
                                            <ChevronDown className="w-5 h-5" />
                                        </button>
                                    </div>
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left font-sans">
                                            <thead>
                                                <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16 text-center">No</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Mata Pelajaran</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">KKM</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Angka</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Grd</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Predikat</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {report.grades.map((sub: any) => (
                                                    <tr key={sub.no} className="hover:bg-neutral-900/30 transition-all group">
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-700 text-xs">{sub.no}</td>
                                                        <td className="px-8 py-6">
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-lg bg-neutral-900 border border-neutral-800 flex items-center justify-center text-[10px] font-black text-neutral-500 group-hover:text-indigo-500 group-hover:border-indigo-500/30 transition-all">
                                                                    {sub.no}
                                                                </div>
                                                                <span className="font-bold text-white text-sm uppercase tracking-tight">{sub.name}</span>
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-600 text-xs">{sub.kkm}</td>
                                                        <td className="px-8 py-6 text-center font-black text-white text-lg tracking-tighter">{sub.score}</td>
                                                        <td className="px-8 py-6 text-center">
                                                            <div className={`w-10 h-10 rounded-xl mx-auto flex items-center justify-center font-black text-sm border ${sub.letter === 'A' ? 'bg-indigo-500 text-white border-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.3)]' :
                                                                sub.letter === 'B' ? 'bg-neutral-900 text-indigo-400 border-neutral-800' :
                                                                    'bg-neutral-900 text-neutral-600 border-neutral-800'
                                                                }`}>
                                                                {sub.letter}
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-6">
                                                            <span className="px-4 py-1.5 bg-neutral-900 text-neutral-500 rounded-xl text-[9px] font-black uppercase tracking-widest border border-neutral-800 group-hover:text-indigo-400 group-hover:border-indigo-500/20 transition-all">
                                                                {sub.predicate}
                                                            </span>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Search,
    ChevronDown,
    Activity,
    AlertTriangle,
    Calendar,
    Filter,
    ArrowLeft,
    ShieldAlert,
    Download
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { homeroomService } from '@/lib/services/homeroom';
import { Loader2 } from 'lucide-react';
import { supabase } from '@/lib/supabase';

export default function PelanggaranWaliPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [categoryFilter, setCategoryFilter] = useState('');

    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [violations, setViolations] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);

    const fetchInitialData = async (userId: string) => {
        try {
            setIsLoading(true);
            const info = await homeroomService.getClassInfo(userId);
            if (!info) {
                setClassInfo({ name: 'Belum Ada Kelas' });
                setIsLoading(false);
                return;
            }
            setClassInfo(info);

            // Fetch violations for students in this class
            const { data, error } = await supabase
                .from('violations')
                .select(`
                    *,
                    students!inner(name, class_id)
                `)
                .eq('students.class_id', info.id)
                .order('violation_date', { ascending: false });

            if (error) throw error;
            setViolations(data || []);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching violations:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
         
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    const filteredData = violations.filter(v => {
        const matchesSearch = v.students?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            v.description?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = categoryFilter === '' || v.category === categoryFilter;
        return matchesSearch && matchesCategory;
    });

    return (
        <div className="min-h-screen bg-black flex flex-col lowercase-none">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <button
                                onClick={() => router.back()}
                                className="flex items-center gap-2 text-neutral-500 hover:text-white transition-colors mb-6 text-xs font-black uppercase tracking-widest group"
                            >
                                <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                                Kembali
                            </button>
                            <div className="flex items-center gap-2 text-rose-500 font-bold text-xs uppercase tracking-[0.2em] mb-3">
                                <ShieldAlert className="w-4 h-4" />
                                Monitoring Kedisiplinan
                            </div>
                            <h1 className="text-3xl lg:text-5xl font-black text-white tracking-tight">
                                Buku <span className="text-rose-500 italic">Kedisplinan</span>
                            </h1>
                            <p className="text-neutral-500 font-medium mt-2">
                                Daftar pelanggaran santri <span className="text-white font-bold">Kelas {classInfo?.name || '...'}</span>.
                            </p>
                        </div>
                        <div className="flex gap-4">
                            <div className="px-6 py-3 bg-rose-600 shadow-xl shadow-rose-900/20 rounded-2xl text-white text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border border-rose-500/20">
                                <AlertTriangle className="w-4 h-4" />
                                {violations.length} Total Kasus
                            </div>
                        </div>
                    </div>

                    {/* Stats Summary (Mini) */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {[
                            { label: 'Ringan', count: violations.filter(v => v.category === 'ringan').length, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                            { label: 'Sedang', count: violations.filter(v => v.category === 'sedang').length, color: 'text-amber-500', bg: 'bg-amber-500/10' },
                            { label: 'Berat', count: violations.filter(v => v.category === 'berat').length, color: 'text-rose-500', bg: 'bg-rose-500/10' },
                        ].map((s, idx) => (
                            <div key={idx} className="bg-[#0c0c0c] p-6 rounded-[2rem] border border-neutral-800 flex items-center justify-between">
                                <p className="text-[10px] font-black text-neutral-500 uppercase tracking-widest">{s.label}</p>
                                <div className={`px-4 py-1 ${s.bg} ${s.color} rounded-lg font-black text-lg border border-white/5`}>
                                    {s.count}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Filters */}
                    <div className="bg-[#0c0c0c] p-8 rounded-[3rem] border border-neutral-800 shadow-2xl">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            <div className="relative group">
                                <Search className="w-5 h-5 text-neutral-600 absolute left-6 top-1/2 -translate-y-1/2 group-focus-within:text-rose-500 transition-colors" />
                                <input
                                    type="text"
                                    placeholder="Cari nama atau deskripsi..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-16 pr-8 py-5 bg-neutral-900 border border-neutral-800 rounded-3xl focus:outline-none focus:ring-4 focus:ring-rose-500/10 focus:bg-black focus:border-rose-500 font-bold text-white transition-all placeholder:text-neutral-700"
                                />
                            </div>
                            <div className="relative group">
                                <select
                                    value={categoryFilter}
                                    onChange={(e) => setCategoryFilter(e.target.value)}
                                    className="w-full h-full pl-8 pr-12 py-5 bg-neutral-900 border border-neutral-800 rounded-3xl focus:outline-none focus:ring-4 focus:ring-rose-500/10 focus:bg-black focus:border-rose-500 font-black text-xs uppercase tracking-widest text-white transition-all appearance-none cursor-pointer"
                                >
                                    <option value="">Semua Tingkat</option>
                                    <option value="ringan">Tingkat Ringan</option>
                                    <option value="sedang">Tingkat Sedang</option>
                                    <option value="berat">Tingkat Berat</option>
                                </select>
                                <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-neutral-600 group-focus-within:text-rose-500 transition-colors">
                                    <ChevronDown className="w-5 h-5" />
                                </div>
                            </div>
                            <div className="flex items-center">
                                <button className="w-full py-5 bg-neutral-900 border border-neutral-800 rounded-3xl text-neutral-400 font-black uppercase tracking-widest text-[10px] hover:text-white hover:bg-neutral-800 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-inner">
                                    <Download className="w-4 h-4" />
                                    Export Excel
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Data List */}
                    <div className="bg-[#0c0c0c] rounded-[3rem] border border-neutral-800 shadow-2xl overflow-hidden group">
                        <div className="hidden lg:block overflow-x-auto">
                            <table className="w-full text-left">
                                <thead className="bg-neutral-900/40 border-b border-neutral-800">
                                    <tr>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Santri</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Tingkat</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Keterangan / Hukuman</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] text-center">Poin</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] text-right">Tanggal</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/50">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={5} className="px-10 py-32 text-center">
                                                <div className="flex flex-col items-center gap-6">
                                                    <Loader2 className="w-16 h-16 text-rose-500 animate-spin" />
                                                    <p className="text-neutral-500 font-black uppercase tracking-[0.3em] text-[10px]">Memuat Rekap Kedisiplinan...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : filteredData.length === 0 ? (
                                        <tr>
                                            <td colSpan={5} className="px-10 py-32 text-center text-neutral-600 font-black uppercase tracking-[0.2em] text-xs italic">
                                                Tidak ada data pelanggaran.
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredData.map((v) => (
                                            <tr key={v.id} className="hover:bg-rose-500/[0.03] transition-colors group/row">
                                                <td className="px-10 py-8">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 bg-neutral-900 rounded-xl flex items-center justify-center text-rose-500 font-black text-[10px] border border-neutral-800 group-hover/row:border-rose-500/30 transition-all">
                                                            {v.students?.name?.charAt(0)}
                                                        </div>
                                                        <p className="font-black text-white group-hover/row:text-rose-400 transition-colors tracking-tight">{v.students?.name}</p>
                                                    </div>
                                                </td>
                                                <td className="px-10 py-8">
                                                    <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black tracking-[0.2em] uppercase border ${v.category === 'berat' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' :
                                                        v.category === 'sedang' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                            'bg-blue-500/10 text-blue-500 border-blue-500/20'
                                                        }`}>
                                                        {v.category}
                                                    </span>
                                                </td>
                                                <td className="px-10 py-8">
                                                    <p className="text-sm font-bold text-neutral-400 group-hover/row:text-neutral-200 transition-colors max-w-md italic leading-relaxed">
                                                        "{v.description || '-'}"
                                                        {v.punishment && <span className="block not-italic text-xs text-rose-400/60 mt-2 font-black uppercase tracking-widest">Takzir: {v.punishment}</span>}
                                                    </p>
                                                </td>
                                                <td className="px-10 py-8 text-center">
                                                    <span className="text-lg font-black text-rose-600 shadow-glow-rose">-{v.points}</span>
                                                </td>
                                                <td className="px-10 py-8 text-right text-[10px] font-black text-neutral-600 uppercase tracking-widest tabular-nums font-mono">
                                                    {new Date(v.violation_date).toLocaleDateString('id-ID')}
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>

                        {/* Mobile List View */}
                        <div className="lg:hidden p-6 space-y-6 bg-black/40">
                            {filteredData.map((v) => (
                                <div key={v.id} className="bg-neutral-900/40 p-8 rounded-[2.5rem] border border-neutral-800 shadow-xl active:scale-[0.98] transition-all group overflow-hidden relative">
                                    <div className="flex items-center justify-between mb-8">
                                        <span className="text-[9px] font-black text-neutral-600 uppercase tracking-[0.2em]">{new Date(v.violation_date).toLocaleDateString('id-ID')}</span>
                                        <span className={`px-5 py-2 rounded-full text-[8px] font-black uppercase tracking-[0.2em] border ${v.category === 'berat' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' :
                                            v.category === 'sedang' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                'bg-blue-500/10 text-blue-500 border-blue-500/20'
                                            }`}>
                                            {v.category}
                                        </span>
                                    </div>
                                    <h4 className="font-black text-white text-xl tracking-tight leading-none mb-6">{v.students?.name}</h4>
                                    <div className="space-y-4 pt-6 border-t border-neutral-800/50">
                                        <p className="text-sm font-medium text-neutral-500 italic leading-relaxed">"{v.description || '-'}"</p>
                                        <div className="flex items-center justify-between">
                                            <p className="text-[9px] font-black text-rose-500/60 uppercase tracking-widest">Poin Disiplin</p>
                                            <p className="text-2xl font-black text-rose-600">-{v.points}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    CalendarCheck,
    Search,
    Filter,
    Clock,
    CheckCircle2,
    XCircle,
    AlertCircle,
    Calendar,
    Loader2,
    Users,
    Activity
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { guardianService } from '@/lib/services/guardian';
import { attendanceService } from '@/lib/services/attendance';

export default function KehadiranSantriPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [children, setChildren] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [activeChild, setActiveChild] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [attendanceLog, setAttendanceLog] = useState<any[]>([]);
    const [stats, setStats] = useState({ hadir: 0, sakit: 0, izin: 0, alpha: 0, percentage: 0 });
    const [searchQuery, setSearchQuery] = useState('');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fetchChildAttendance = async (child: any) => {
        setIsLoading(true);
        setActiveChild(child);
        try {
            const data = await attendanceService.getStudentHistory(child.id);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const formatted = data.map((item: any) => ({
                id: item.id,
                date: new Date(item.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }),
                day: new Date(item.date).toLocaleDateString('id-ID', { weekday: 'long' }),
                status: item.status.charAt(0).toUpperCase() + item.status.slice(1),
                checkIn: item.check_in_time ? item.check_in_time.slice(0, 5) : '-',
                session: item.session || item.type || 'Kegiatan Umum',
                notes: item.notes
            }));

            setAttendanceLog(formatted);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const counts = data.reduce((acc: any, curr: any) => {
                acc[curr.status] = (acc[curr.status] || 0) + 1;
                return acc;
            }, { hadir: 0, sakit: 0, izin: 0, alpha: 0 });

            const total = data.length || 1;
            setStats({
                ...counts,
                percentage: Math.round((counts.hadir / total) * 100)
            });
        } catch (err) {
            console.error('Error fetching attendance:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchInitialData = useCallback(async (parentId: string) => {
        try {
            const childrenList = await guardianService.getChildren(parentId);
            setChildren(childrenList);
            if (childrenList.length > 0) {
                await fetchChildAttendance(childrenList[0]);
            } else {
                setIsLoading(false);
            }
        } catch (err) {
            console.error('Error fetching initial data:', err);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchInitialData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && !activeChild) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-orange-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyinkronkan Data Kehadiran...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const filteredLogs = attendanceLog.filter(log =>
        log.date.toLowerCase().includes(searchQuery.toLowerCase()) ||
        log.session.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-orange-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-orange-500 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Discipline Monitoring
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Kehadiran & <span className="text-orange-500">Kedisiplinan Santri</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Laporan kehadiran harian dan riwayat absensi aktivitas pesantren.</p>
                        </div>

                        {children.length > 1 && (
                            <div className="flex bg-[#0a0a0a] p-1.5 rounded-2xl border border-neutral-800 shadow-xl overflow-x-auto no-scrollbar">
                                {children.map(c => (
                                    <button
                                        key={c.id}
                                        onClick={() => fetchChildAttendance(c)}
                                        className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all shrink-0 ${activeChild?.id === c.id
                                            ? 'bg-orange-600 text-white shadow-[0_0_15px_rgba(234,88,12,0.3)]'
                                            : 'text-neutral-600 hover:text-neutral-300'
                                            }`}
                                    >
                                        {c.name.split(' ')[0]}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {!activeChild ? (
                        <div className="bg-[#0a0a0a] border border-neutral-800/50 rounded-[3rem] p-24 text-center shadow-2xl">
                            <Users className="w-20 h-20 text-neutral-800 mx-auto mb-6" />
                            <h3 className="text-2xl font-black text-white">Data Belum Tersedia</h3>
                            <p className="text-neutral-500 mt-2 font-medium">Sistem sedang menyiapkan data kehadiran untuk akun Anda.</p>
                        </div>
                    ) : (
                        <>
                            {/* Stats Summary Cards */}
                            <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <CheckCircle2 className="w-6 h-6 text-emerald-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.percentage}%</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2 text-center">Rasio Kehadiran</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-amber-500/5 border border-amber-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <AlertCircle className="w-6 h-6 text-amber-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.izin}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Total Izin</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-blue-500/5 border border-blue-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <Calendar className="w-6 h-6 text-blue-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.sakit}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Total Sakit</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-rose-500/5 border border-rose-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <XCircle className="w-6 h-6 text-rose-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.alpha}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Tanpa Ket.</p>
                                </div>
                            </div>

                            {/* Filtering & Search */}
                            <div className="flex flex-col md:flex-row gap-6 items-center justify-between">
                                <div className="relative w-full md:w-96">
                                    <Search className="w-5 h-5 text-neutral-700 absolute left-5 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="text"
                                        placeholder="Cari tanggal atau aktivitas..."
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        className="w-full pl-14 pr-6 py-4 bg-[#0a0a0a] border border-neutral-800/50 rounded-2xl focus:outline-none focus:border-orange-500/30 text-white font-medium shadow-xl transition-all"
                                    />
                                </div>
                                <div className="flex gap-3 w-full md:w-auto">
                                    <button className="flex-1 md:flex-none flex items-center justify-center gap-3 px-8 py-4 bg-neutral-900 border border-neutral-800 text-neutral-400 font-black rounded-2xl hover:text-white transition-all text-[10px] uppercase tracking-widest">
                                        <Filter className="w-4 h-4" />
                                        Filter Status
                                    </button>
                                </div>
                            </div>

                            {/* Attendance Log Table */}
                            <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden min-h-[400px]">
                                {isLoading ? (
                                    <div className="flex items-center justify-center h-[400px]">
                                        <Loader2 className="w-10 h-10 text-orange-500 animate-spin opacity-40" />
                                    </div>
                                ) : filteredLogs.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-[400px] text-gray-400">
                                        <div className="w-20 h-20 bg-neutral-900 rounded-[2rem] flex items-center justify-center mb-6 border border-neutral-800 opacity-20">
                                            <CalendarCheck className="w-10 h-10" />
                                        </div>
                                        <p className="font-bold italic uppercase text-[10px] tracking-widest opacity-30">Belum ada riwayat kehadiran tercatat.</p>
                                    </div>
                                ) : (
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left">
                                            <thead className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                                <tr>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-48">Tanggal / Hari</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Aktivitas / Sesi</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Status</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Jam</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Keterangan</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {filteredLogs.map((item) => (
                                                    <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                        <td className="px-8 py-7">
                                                            <p className="font-black text-white text-sm uppercase tracking-tight">{item.date}</p>
                                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1.5">{item.day}</p>
                                                        </td>
                                                        <td className="px-8 py-7">
                                                            <div className="flex items-center gap-4">
                                                                <div className="w-10 h-10 bg-orange-500/5 border border-orange-500/10 rounded-xl flex items-center justify-center group-hover:bg-orange-600 transition-all group-hover:shadow-[0_0_15px_rgba(234,88,12,0.3)]">
                                                                    <Clock className="w-4 h-4 text-orange-500 group-hover:text-white" />
                                                                </div>
                                                                <p className="font-bold text-white text-sm uppercase tracking-tight">{item.session}</p>
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-7 text-center">
                                                            <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${item.status === 'Hadir' ? 'bg-emerald-500/5 text-emerald-500 border-emerald-500/10 shadow-[0_0_10px_rgba(16,185,129,0.05)]' :
                                                                item.status === 'Izin' ? 'bg-amber-500/5 text-amber-500 border-amber-500/10' :
                                                                    item.status === 'Sakit' ? 'bg-blue-500/5 text-blue-500 border-blue-500/10' :
                                                                        'bg-rose-500/5 text-rose-500 border-rose-500/10'
                                                                }`}>
                                                                {item.status}
                                                            </span>
                                                        </td>
                                                        <td className="px-8 py-7 text-center">
                                                            <span className={`text-[10px] font-black tracking-widest uppercase ${item.checkIn !== '-' ? 'text-white' : 'text-neutral-800'}`}>
                                                                {item.checkIn}
                                                            </span>
                                                        </td>
                                                        <td className="px-8 py-7">
                                                            <p className="text-xs text-neutral-500 font-medium italic max-w-xs truncate">
                                                                "{item.notes || 'Tidak ada catatan khusus.'}"
                                                            </p>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </div>
                        </>
                    )}
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    BookOpen,
    Search,
    ChevronRight,
    MessageSquare,
    Trophy,
    Target,
    Loader2,
    Users,
    Clock,
    CheckCircle2,
    Activity,
    Star,
    LayoutGrid,
    History as HistoryIcon
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { guardianService } from '@/lib/services/guardian';
import { hafalanService } from '@/lib/services/hafalan';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function ProgressTahfidzPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [children, setChildren] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [activeChild, setActiveChild] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [history, setHistory] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [summary, setSummary] = useState<any>(null);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fetchChildHafalan = async (child: any) => {
        setIsLoading(true);
        setActiveChild(child);
        try {
            const [historyData, dashboardData] = await Promise.all([
                hafalanService.getByStudent(child.id),
                studentDashboardService.getHafalanData(child.id)
            ]);

            setHistory(historyData);
            setSummary(dashboardData);
        } catch (err) {
            console.error('Error fetching child hafalan:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchInitialData = useCallback(async (parentId: string) => {
        try {
            const childrenList = await guardianService.getChildren(parentId);
            setChildren(childrenList);
            if (childrenList.length > 0) {
                await fetchChildHafalan(childrenList[0]);
            } else {
                setIsLoading(false);
            }
        } catch (err) {
            console.error('Error fetching initial data:', err);
            setIsLoading(false);
        }
    }, [fetchChildHafalan]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchInitialData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return '-';
        return new Date(dateString).toLocaleDateString('id-ID', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    const getGradeConfig = (grade: string | null) => {
        if (!grade) return { label: '-', color: 'text-neutral-500 bg-neutral-900 border-neutral-800' };
        const configs: Record<string, any> = {
            'A': { label: 'Mumtaz', color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' },
            'B': { label: 'Jayyid Jiddan', color: 'text-blue-400 bg-blue-500/10 border-blue-500/20' },
            'C': { label: 'Jayyid', color: 'text-amber-400 bg-amber-500/10 border-amber-500/20' },
            'D': { label: 'Maqbul', color: 'text-orange-400 bg-orange-500/10 border-orange-500/20' },
            'E': { label: 'Dhaif', color: 'text-rose-400 bg-rose-500/10 border-rose-500/20' },
        };
        return configs[grade] || { label: grade, color: 'text-neutral-400 bg-neutral-900 border-neutral-800' };
    };

    if (isLoading && !activeChild) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
