'use client';

import { useState } from 'react';
import { supabase } from '@/lib/supabase';
import { CheckCircle, XCircle, Loader2, UserPlus } from 'lucide-react';

const DEMO_USERS = [
    { email: 'admin@pesantren.com', password: 'admin123', name: 'Super Admin', role: 'super_admin' },
    { email: 'keuangan@pesantren.com', password: 'keuangan123', name: 'Admin Keuangan', role: 'admin_keuangan' },
    { email: 'akademik@pesantren.com', password: 'akademik123', name: 'Admin Akademik', role: 'admin_akademik' },
    { email: 'kesantrian@pesantren.com', password: 'kesantrian123', name: 'Staff Kesantrian', role: 'kesantrian' },
    { email: 'ustadz@pesantren.com', password: 'ustadz123', name: 'Ustadz Ahmad', role: 'ustadz' },
    { email: 'walikelas@pesantren.com', password: 'walikelas123', name: 'Wali Kelas 7A', role: 'wali_kelas' },
    { email: 'wali@pesantren.com', password: 'wali123', name: 'Bpk. Ahmad', role: 'wali_santri' },
    { email: 'santri@pesantren.com', password: 'santri123', name: 'Muhammad Rizki', role: 'santri' },
];

interface UserStatus {
    email: string;
    status: 'pending' | 'success' | 'error' | 'exists';
    message: string;
}

export default function SeederPage() {
    const [statuses, setStatuses] = useState<UserStatus[]>([]);
    const [isRunning, setIsRunning] = useState(false);

    const createUsers = async () => {
        setIsRunning(true);
        setStatuses([]);

        for (const user of DEMO_USERS) {
            // Update status to pending
            setStatuses(prev => [...prev, {
                email: user.email,
                status: 'pending',
                message: 'Membuat user...'
            }]);

            try {
                // Try to sign up the user
                const { data, error } = await supabase.auth.signUp({
                    email: user.email,
                    password: user.password,
                    options: {
                        data: {
                            name: user.name,
                            role: user.role,
                        },
                    },
                });

                if (error) {
                    if (error.message.includes('already registered')) {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'exists', message: 'User sudah terdaftar' }
                                : s
                            )
                        );
                    } else {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'error', message: error.message }
                                : s
                            )
                        );
                    }
                } else if (data.user) {
                    // User created, now update profile role
                    const { error: profileError } = await supabase
                        .from('profiles')
                        .upsert({
                            id: data.user.id,
                            email: user.email,
                            name: user.name,
                            role: user.role,
                        });

                    if (profileError) {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'error', message: `Profile error: ${profileError.message}` }
                                : s
                            )
                        );
                    } else {
                        setStatuses(prev =>
                            prev.map(s => s.email === user.email
                                ? { ...s, status: 'success', message: 'Berhasil dibuat!' }
                                : s
                            )
                        );
                    }
                }
            } catch (err: any) {
                setStatuses(prev =>
                    prev.map(s => s.email === user.email
                        ? { ...s, status: 'error', message: err.message }
                        : s
                    )
                );
            }

            // Small delay between users
            await new Promise(r => setTimeout(r, 500));
        }

        setIsRunning(false);
    };

    const getStatusIcon = (status: UserStatus['status']) => {
        switch (status) {
            case 'success': return <CheckCircle className="w-5 h-5 text-green-600" />;
            case 'error': return <XCircle className="w-5 h-5 text-red-600" />;
            case 'exists': return <CheckCircle className="w-5 h-5 text-yellow-600" />;
            default: return <Loader2 className="w-5 h-5 text-gray-400 animate-spin" />;
        }
    };

    const getStatusColor = (status: UserStatus['status']) => {
        switch (status) {
            case 'success': return 'bg-green-50 border-green-200';
            case 'error': return 'bg-red-50 border-red-200';
            case 'exists': return 'bg-yellow-50 border-yellow-200';
            default: return 'bg-gray-50 border-gray-200';
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-emerald-50 via-white to-amber-50 p-8">
            <div className="max-w-2xl mx-auto">
                <div className="bg-white rounded-2xl shadow-lg p-8">
                    <div className="flex items-center gap-3 mb-6">
                        <UserPlus className="w-8 h-8 text-emerald-600" />
                        <h1 className="text-2xl font-bold text-gray-800">
                            Buat User Demo
                        </h1>
                    </div>

                    <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                        <p className="text-sm text-blue-800">
                            <strong>ℹ️ Info:</strong> Halaman ini membuat 8 user demo untuk testing.
                            User akan dibuat via Supabase Auth API (bukan SQL langsung).
                        </p>
                    </div>

                    {statuses.length > 0 && (
                        <div className="space-y-3 mb-6">
                            {statuses.map((status, index) => (
                                <div
                                    key={index}
                                    className={`flex items-center gap-3 p-3 rounded-lg border ${getStatusColor(status.status)}`}
                                >
                                    {getStatusIcon(status.status)}
                                    <div className="flex-1">
                                        <p className="font-medium text-gray-800">{status.email}</p>
                                        <p className="text-sm text-gray-600">{status.message}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    <button
                        onClick={createUsers}
                        disabled={isRunning}
                        className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors font-medium"
                    >
                        {isRunning ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Membuat User...
                            </>
                        ) : (
                            <>
                                <UserPlus className="w-5 h-5" />
                                Buat 8 User Demo
                            </>
                        )}
                    </button>

                    <div className="mt-8 border-t pt-6">
                        <h3 className="font-semibold text-gray-700 mb-3">Daftar Akun Demo:</h3>
                        <div className="grid grid-cols-2 gap-2 text-sm">
                            {DEMO_USERS.map((user, i) => (
                                <div key={i} className="text-gray-600">
                                    <span className="font-medium">{user.role}:</span> {user.email}
                                </div>
                            ))}
                        </div>
                        <p className="mt-3 text-xs text-gray-500">
                            Password masing-masing: nama role + 123 (contoh: admin123)
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { supabase, isSupabaseConfigured } from '@/lib/supabase';
import { CheckCircle, XCircle, Loader2, Database, Shield, RefreshCw } from 'lucide-react';

interface TestResult {
    name: string;
    status: 'pending' | 'success' | 'error';
    message: string;
}

export default function TestConnectionPage() {
    const [results, setResults] = useState<TestResult[]>([]);
    const [isRunning, setIsRunning] = useState(false);

    const runTests = async () => {
        setIsRunning(true);
        setResults([]);

        const testResults: TestResult[] = [];

        // Test 1: Environment Variables
        testResults.push({
            name: 'Environment Variables',
            status: isSupabaseConfigured() ? 'success' : 'error',
            message: isSupabaseConfigured()
                ? 'SUPABASE_URL dan ANON_KEY terkonfigurasi'
                : 'Environment variables belum diset di .env.local'
        });
        setResults([...testResults]);

        if (!isSupabaseConfigured()) {
            setIsRunning(false);
            return;
        }

        // Test 2: Auth Connection
        try {
            const { data: session, error } = await supabase.auth.getSession();
            testResults.push({
                name: 'Auth Service',
                status: error ? 'error' : 'success',
                message: error
                    ? `Error: ${error.message}`
                    : `Terkoneksi (Session: ${session?.session ? 'Aktif' : 'Tidak ada'})`
            });
        } catch (err: any) {
            testResults.push({
                name: 'Auth Service',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        // Test 3: Database Query (tabel test)
        try {
            const { data, error } = await supabase.from('test').select('*').limit(5);

            if (error) {
                if (error.code === '42P01') {
                    testResults.push({
                        name: 'Query Tabel "test"',
                        status: 'error',
                        message: 'Tabel "test" belum ada. Buat di SQL Editor.'
                    });
                } else {
                    testResults.push({
                        name: 'Query Tabel "test"',
                        status: 'error',
                        message: `Error: ${error.message}`
                    });
                }
            } else {
                testResults.push({
                    name: 'Query Tabel "test"',
                    status: 'success',
                    message: `Berhasil! Ditemukan ${data?.length || 0} row(s)`
                });
            }
        } catch (err: any) {
            testResults.push({
                name: 'Query Tabel "test"',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        // Test 4: Database Query (tabel profiles - dari schema)
        try {
            const { data, error } = await supabase.from('profiles').select('id, email, role').limit(5);

            if (error) {
                if (error.code === '42P01') {
                    testResults.push({
                        name: 'Query Tabel "profiles"',
                        status: 'error',
                        message: 'Tabel belum ada. Deploy schema.sql terlebih dahulu.'
                    });
                } else {
                    testResults.push({
                        name: 'Query Tabel "profiles"',
                        status: 'error',
                        message: `Error: ${error.message}`
                    });
                }
            } else {
                testResults.push({
                    name: 'Query Tabel "profiles"',
                    status: 'success',
                    message: `Berhasil! Ditemukan ${data?.length || 0} user(s)`
                });
            }
        } catch (err: any) {
            testResults.push({
                name: 'Query Tabel "profiles"',
                status: 'error',
                message: `Exception: ${err.message}`
            });
        }
        setResults([...testResults]);

        setIsRunning(false);
    };

    useEffect(() => {
        runTests();
    }, []);

    return (
        <div className="min-h-screen bg-gradient-to-br from-emerald-50 via-white to-amber-50 p-8">
            <div className="max-w-2xl mx-auto">
                <div className="bg-white rounded-2xl shadow-lg p-8">
                    <div className="flex items-center gap-3 mb-6">
                        <Database className="w-8 h-8 text-emerald-600" />
                        <h1 className="text-2xl font-bold text-gray-800">
                            Test Koneksi Supabase
                        </h1>
                    </div>

                    <div className="mb-6 p-4 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-600 mb-2">
                            <strong>Project URL:</strong>
                        </p>
                        <code className="text-xs bg-gray-200 px-2 py-1 rounded">
                            {process.env.NEXT_PUBLIC_SUPABASE_URL || 'Tidak dikonfigurasi'}
                        </code>
                    </div>

                    <div className="space-y-4 mb-6">
                        {results.map((result, index) => (
                            <div
                                key={index}
                                className={`flex items-start gap-3 p-4 rounded-lg border ${result.status === 'success'
                                        ? 'bg-green-50 border-green-200'
                                        : result.status === 'error'
                                            ? 'bg-red-50 border-red-200'
                                            : 'bg-gray-50 border-gray-200'
                                    }`}
                            >
                                {result.status === 'success' && (
                                    <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                                )}
                                {result.status === 'error' && (
                                    <XCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                                )}
                                {result.status === 'pending' && (
                                    <Loader2 className="w-5 h-5 text-gray-400 animate-spin flex-shrink-0 mt-0.5" />
                                )}
                                <div>
                                    <p className="font-medium text-gray-800">{result.name}</p>
                                    <p className="text-sm text-gray-600">{result.message}</p>
                                </div>
                            </div>
                        ))}

                        {isRunning && results.length < 4 && (
                            <div className="flex items-center gap-3 p-4 rounded-lg bg-gray-50 border border-gray-200">
                                <Loader2 className="w-5 h-5 text-emerald-600 animate-spin" />
                                <p className="text-gray-600">Menjalankan test...</p>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={runTests}
                        disabled={isRunning}
                        className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        <RefreshCw className={`w-4 h-4 ${isRunning ? 'animate-spin' : ''}`} />
                        {isRunning ? 'Testing...' : 'Jalankan Ulang Test'}
                    </button>

                    <div className="mt-8 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                        <p className="text-sm text-amber-800">
                            <strong>💡 Tips:</strong> Jika test gagal, pastikan:
                        </p>
                        <ul className="text-sm text-amber-700 mt-2 list-disc list-inside space-y-1">
                            <li>File <code>.env.local</code> sudah dibuat dengan kredensial yang benar</li>
                            <li>Restart dev server setelah membuat <code>.env.local</code></li>
                            <li>Schema database sudah di-deploy ke Supabase</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
}

