'use client';

import { useRef, useMemo, useState, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, GradientTexture, Stars, Torus } from '@react-three/drei';
import * as THREE from 'three';
import MobileFallbackBackground from './MobileFallbackBackground';

function AnimatedSphere() {
    const meshRef = useRef<THREE.Mesh>(null);

    useFrame((state) => {
        if (meshRef.current) {
            meshRef.current.rotation.x = state.clock.getElapsedTime() * 0.2;
            meshRef.current.rotation.y = state.clock.getElapsedTime() * 0.3;
        }
    });

    return (

        <Float speed={2} rotationIntensity={1} floatIntensity={2}>

            <Sphere ref={meshRef} args={[1.5, 64, 64]} scale={1.2}>

                <MeshDistortMaterial
                    distort={0.4}
                    speed={4}
                    roughness={0.2}
                    metalness={0.8}
                    color="#f97316"
                >

                    <GradientTexture
                        stops={[0, 1]}
                        colors={['#f97316', '#7c2d12']}
                    />

                </MeshDistortMaterial>

            </Sphere>

        </Float>
    );
}

function Rings() {
    const ringRotations = useMemo(() => {
        return [...Array(3)].map(() => [
            Math.random() * Math.PI,
            Math.random() * Math.PI,
            0
        ] as [number, number, number]);
    }, []);

    return (
        <group>
            {ringRotations.map((rotation, i) => (

                <Float key={i} speed={1} rotationIntensity={0.5} floatIntensity={0.5}>

                    <Torus args={[3 + i * 1, 0.02, 16, 100]} rotation={rotation}>

                        <meshBasicMaterial color="#f97316" transparent opacity={0.1 - i * 0.02} />

                    </Torus>
                </Float>
            ))}
        </group>
    );
}

function Particles({ count = 2000 }) {
    const points = useMemo(() => {
        const p = new Float32Array(count * 3);
        for (let i = 0; i < count; i++) {
            p[i * 3] = (Math.random() - 0.5) * 15;
            p[i * 3 + 1] = (Math.random() - 0.5) * 15;
            p[i * 3 + 2] = (Math.random() - 0.5) * 15;
        }
        return p;
    }, [count]);

    return (

        <points>

            <bufferGeometry>

                <bufferAttribute
                    attach="attributes-position"
                    args={[points, 3]}
                />

            </bufferGeometry>

            <pointsMaterial size={0.03} color="#f97316" transparent opacity={0.4} sizeAttenuation />

        </points>
    );
}

export default function LoginHero3D() {
    const [isMobile, setIsMobile] = useState(false);
    const [isClient, setIsClient] = useState(false);

    useEffect(() => {
        setIsClient(true);
        // Detect mobile devices or Capacitor environment
        const checkMobile = () => {
            const userAgent = navigator.userAgent || navigator.vendor;
            const isMobileDevice = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(userAgent);
            const isSmallScreen = window.innerWidth < 900; // Lower threshold to catch "Desktop Mode" (usually 980px)
            const isCapacitor = typeof (window as unknown as { Capacitor: unknown }).Capacitor !== 'undefined';

            // If it's a mobile device but has a LARGE screen (Desktop Mode), don't treat as mobile
            if (isMobileDevice && !isSmallScreen) return false;

            return isMobileDevice || isSmallScreen || isCapacitor;
        };
        setIsMobile(checkMobile());

        const handleResize = () => setIsMobile(checkMobile());
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Server-side render nothing, client will hydrate
    if (!isClient) {
        return <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none bg-[#050505]" />;
    }

    // Use lightweight CSS fallback for mobile devices
    if (isMobile) {
        return <MobileFallbackBackground />;
    }

    return (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">

            <Canvas camera={{ position: [0, 0, 8], fov: 75 }}>

                <ambientLight intensity={0.5} />

                <pointLight position={[10, 10, 10]} intensity={1.5} color="#f97316" />

                <pointLight position={[-10, -10, -10]} intensity={0.5} color="#7c2d12" />

                <Stars radius={100} depth={50} count={3000} factor={4} saturation={0} fade speed={1} />

                <AnimatedSphere />

                <Rings />

                <Particles count={1500} />

                <fog attach="fog" args={['#050505', 5, 20]} />
            </Canvas>
        </div>
    );
}

'use client';
import { useState, useEffect } from 'react';

/**
 * Mobile Fallback Background
 * A lightweight CSS-only animated background for mobile devices
 * to replace the heavy 3D WebGL animation
 */
export default function MobileFallbackBackground() {
    return (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none bg-transparent">
            {/* Animated Gradient Orbs */}
            <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-orange-600/20 rounded-full blur-[100px] animate-pulse" />
            <div className="absolute bottom-1/4 right-1/4 w-48 h-48 bg-amber-500/15 rounded-full blur-[80px] animate-pulse" style={{ animationDelay: '1s' }} />
            <div className="absolute top-1/2 right-1/3 w-32 h-32 bg-orange-400/10 rounded-full blur-[60px] animate-pulse" style={{ animationDelay: '2s' }} />

            {/* Floating Particles */}
            const [particles, setParticles] = useState<{ top: string; left: string; delay: string; duration: string }[]>([]);

    useEffect(() => {
        const newParticles = [...Array(15)].map(() => ({
                top: `${Math.random() * 100}%`,
            left: `${Math.random() * 100}%`,
            delay: `${Math.random() * 5}s`,
            duration: `${4 + Math.random() * 4}s`
        }));
            setParticles(newParticles);
    }, []);

            return (
            <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none bg-transparent">
                {/* Animated Gradient Orbs */}
                <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-orange-600/20 rounded-full blur-[100px] animate-pulse" />
                <div className="absolute bottom-1/4 right-1/4 w-48 h-48 bg-amber-500/15 rounded-full blur-[80px] animate-pulse" style={{ animationDelay: '1s' }} />
                <div className="absolute top-1/2 right-1/3 w-32 h-32 bg-orange-400/10 rounded-full blur-[60px] animate-pulse" style={{ animationDelay: '2s' }} />

                {/* Floating Particles */}
                {particles.map((p, i) => (
                    <div
                        key={i}
                        className="absolute w-1 h-1 bg-orange-500/30 rounded-full animate-float"
                        style={{
                            top: p.top,
                            left: p.left,
                            animationDelay: p.delay,
                            animationDuration: p.duration
                        }}
                    />
                ))}

                {/* Orbital Ring Effect */}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
                    <div className="w-48 h-48 border border-orange-500/10 rounded-full animate-spin-slow" />
                    <div className="absolute inset-4 border border-orange-500/5 rounded-full animate-spin-reverse" />
                </div>

                {/* Grid Pattern Overlay */}
                <div
                    className="absolute inset-0 opacity-[0.02]"
                    style={{
                        backgroundImage: `
                        linear-gradient(rgba(249,115,22,0.1) 1px, transparent 1px),
                        linear-gradient(90deg, rgba(249,115,22,0.1) 1px, transparent 1px)
                    `,
                        backgroundSize: '50px 50px'
                    }}
                />
            </div>
            );
}

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';

interface ViolationData {
    violation_date: string;
    student_id: string;
    students: {
        name: string;
        classes: {
            name: string;
        } | null;
    } | null;
    category: string;
    description: string;
    points: number;
    // reported_by handled but not displaying name for now
}

interface TopViolatorData {
    student_name: string;
    class_name: string;
    total_points: number;
    violation_count: number;
}

interface PermissionData {
    studentName: string;
    studentClass: string;
    reason: string;
    startDate: string;
    endDate: string;
    status: string;
}

interface DormData {
    name: string;
    capacity: number;
    current_occupancy: number;
    supervisor?: { name: string };
}

export const generatePDF = (reportId: string, data: any[], pesantrenName: string = 'Smart Pesantren') => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.width;
    const today = format(new Date(), 'dd MMMM yyyy', { locale: id });

    // HEADER
    doc.setFontSize(18);
    doc.text(pesantrenName, pageWidth / 2, 15, { align: 'center' });
    doc.setFontSize(12);
    doc.text('Laporan Bagian Kesantrian', pageWidth / 2, 22, { align: 'center' });
    doc.setFontSize(10);
    doc.text(`Tanggal Cetak: ${today}`, pageWidth / 2, 28, { align: 'center' });
    doc.line(15, 32, pageWidth - 15, 32);

    let title = '';
    let columns: string[] = [];
    let rows: any[][] = [];

    switch (reportId) {
        case 'monthly-violations':
            title = 'Laporan Pelanggaran Bulanan';
            columns = ['No', 'Tanggal', 'Nama Santri', 'Kelas', 'Kategori', 'Poin', 'Keterangan'];
            rows = data.map((item: ViolationData, index) => [
                index + 1,
                format(new Date(item.violation_date), 'dd/MM/yyyy'),
                item.students?.name || '-',
                item.students?.classes?.name || '-',
                item.category?.toUpperCase() || '-',
                item.points,
                item.description || '-'
            ]);
            break;

        case 'top-offenders':
            title = 'Santri Top Poin (Bermasalah)';
            columns = ['Ranking', 'Nama Santri', 'Kelas', 'Total Poin', 'Jumlah Pelanggaran', 'Status'];
            rows = data.map((item: TopViolatorData, index) => [
                index + 1,
                item.student_name,
                item.class_name,
                item.total_points,
                item.violation_count,
                item.total_points >= 50 ? 'SP 1' : item.total_points >= 20 ? 'Perhatian' : 'Aman'
            ]);
            break;

        case 'permits-summary':
            title = 'Rekap Perizinan Keluar';
            columns = ['No', 'Nama Santri', 'Kelas', 'Alasan', 'Tgl Keluar', 'Tgl Kembali', 'Status'];
            rows = data.map((item: PermissionData, index) => [
                index + 1,
                item.studentName,
                item.studentClass,
                item.reason,
                item.startDate,
                item.endDate,
                item.status.toUpperCase()
            ]);
            break;

        case 'dorm-occupancy':
            title = 'Laporan Okupansi Asrama';
            columns = ['No', 'Nama Asrama', 'Musyrif', 'Kapasitas', 'Terisi', 'Sisa', 'Persentase'];
            rows = data.map((item: DormData, index) => {
                const percentage = Math.round((item.current_occupancy / item.capacity) * 100);
                return [
                    index + 1,
                    item.name,
                    item.supervisor?.name || '-',
                    item.capacity,
                    item.current_occupancy,
                    item.capacity - item.current_occupancy,
                    `${percentage}%`
                ];
            });
            break;
    }

    doc.setFontSize(14);
    doc.text(title, 15, 45);

    autoTable(doc, {
        head: [columns],
        body: rows,
        startY: 50,
        styles: { fontSize: 8, cellPadding: 2 },
        headStyles: { fillColor: [22, 163, 74], textColor: 255 }, // Emerald green head
        alternateRowStyles: { fillColor: [240, 253, 244] }, // Light emerald alternate
    });

    // FOOTER (Signature)
    const finalY = (doc as any).lastAutoTable.finalY + 20;

    // Check if we need a new page for signature
    if (finalY > doc.internal.pageSize.height - 40) {
        doc.addPage();
        // new page y start
    }

    // Simple signature placeholder
    const sigY = finalY > doc.internal.pageSize.height - 40 ? 40 : finalY;

    doc.setFontSize(10);
    doc.text('Mengetahui,', pageWidth - 50, sigY, { align: 'center' });
    doc.text('Kepala Bagian Kesantrian', pageWidth - 50, sigY + 5, { align: 'center' });
    doc.text('( ................................. )', pageWidth - 50, sigY + 25, { align: 'center' });

    doc.save(`${reportId}-${format(new Date(), 'yyyy-MM-dd')}.pdf`);
};

import { supabase } from '../supabase';

// Update interface to allow null/undefined status initially
export interface AttendanceItem {
    student_id: string;
    student_name: string;
    class_name?: string;
    nis: string;
    status: 'hadir' | 'izin' | 'sakit' | 'alpha' | 'telat' | null;
    notes: string;
}

export interface AttendanceStats {
    totalStudents: number;
    presentToday: number;
    sickPermissionToday: number;
    alphaToday: number;
}

export interface AttendanceRekapItem {
    id: string;
    studentId: string;
    studentName: string;
    studentClass: string;
    classId: string;
    session: string;
    status: string;
    date: string;
}



export const attendanceService = {
    // 1. Get Class Roster with attendance status for a specific date
    async getClassAttendance(
        classId: string | null,
        date: string,
        session?: string,
        type: string = 'class'
    ): Promise<AttendanceItem[]> {
        const { data, error } = await supabase.rpc('get_class_attendance_status', {
            p_class_id: classId == 'all' ? null : classId,
            p_date: date,
            p_session: session,
            p_type: type
        });

        if (error) {
            console.error('Error fetching class attendance:', error);
            throw error;
        }

        return (data || []).map((item: { student_id: string, student_name: string, class_name: string, nis: string, status: string | null, notes: string | null }) => ({
            student_id: item.student_id,
            student_name: item.student_name,
            class_name: item.class_name,
            nis: item.nis,
            // Status remains null if from DB is null. We handle default in UI Page based on Class Selection.
            status: item.status as AttendanceItem['status'],
            notes: item.notes || ''
        }));
    },
    // 2. Submit Attendance (Batch)
    async submitAttendance(
        date: string,
        attendanceList: AttendanceItem[],
        recordedBy: string,
        session?: string, // e.g. "Madin"
        type: string = 'class' // 'class', 'prayer', etc.
    ) {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        // Transform to minimal payload for RPC
        const payload = attendanceList.map(item => ({
            student_id: item.student_id,
            status: item.status,
            notes: item.notes
        }));

        console.log('Payload:', JSON.stringify(payload));
        const { data, error } = await supabase.rpc('submit_class_attendance', {
            p_date: date,
            p_attendance_list: payload,
            p_recorded_by: recordedBy,
            p_pesantren_id: pesantrenId,
            p_session: session,
            p_type: type
        });

        if (error) {
            console.error('Error submitting attendance RPC:', error);
            throw error;
        }

        return data;
    },

    // 3. Get Attendance Statistics for Dashboard
    async getStats(): Promise<AttendanceStats> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();
        const today = new Date().toISOString().split('T')[0];

        // Get total students
        let studentQuery = supabase
            .from('students')
            .select('*', { count: 'exact', head: true })
            .eq('status', 'active');

        if (pesantrenId) {
            studentQuery = studentQuery.eq('pesantren_id', pesantrenId);
        }

        const { count: totalStudents } = await studentQuery;

        // Get today's attendance
        let attendanceQuery = supabase
            .from('attendance')
            .select('status')
            .eq('date', today);

        if (pesantrenId) {
            attendanceQuery = attendanceQuery.eq('pesantren_id', pesantrenId);
        }

        // Filter removed to include ALL attendance types (Prayer, Class, Activity)
        // attendanceQuery = attendanceQuery.in('type', ['class', 'academic']);

        const { data: todayAttendance } = await attendanceQuery;

        const presentToday = todayAttendance?.filter(a => a.status === 'hadir').length || 0;
        const sickPermissionToday = todayAttendance?.filter(a => a.status === 'sakit' || a.status === 'izin').length || 0;
        const alphaToday = todayAttendance?.filter(a => a.status === 'alpha').length || 0;

        return {
            totalStudents: totalStudents || 0,
            presentToday,
            sickPermissionToday,
            alphaToday
        };
    },

    // 4. Get Presence Meter (percentage)
    async getPresenceMeter(): Promise<number> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();
        const today = new Date().toISOString().split('T')[0];

        let query = supabase
            .from('attendance')
            .select('status')
            .eq('date', today);
        // .in('type', ['class', 'academic']); // Focus on school/academic attendance

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data } = await query;

        if (!data || data.length === 0) return 100;

        const present = data.filter(a => a.status === 'hadir').length;
        return Math.round((present / data.length) * 100);
    },

    // 5. Get Session Alpha (for bar chart)
    async getSessionAlpha(): Promise<{ name: string; alpha: number }[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();
        const today = new Date().toISOString().split('T')[0];

        let query = supabase
            .from('attendance')
            .select('session, status')
            .eq('date', today)
            .eq('status', 'alpha');

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data } = await query;

        // Group by session name
        const counts: Record<string, number> = {};

        (data || []).forEach((row: { session: string | null; status: string }) => {
            const sessionName = row.session || 'Umum';
            counts[sessionName] = (counts[sessionName] || 0) + 1;
        });

        // Convert to array
        const result = Object.keys(counts).map(key => ({
            name: key,
            alpha: counts[key]
        }));

        // If empty, return dummy structure to avoid chart crash, but with 0 values? 
        // No, better return empty or specific empty state in UI.
        // Let's return at least one if empty so chart renders valid empty state if needed.
        if (result.length === 0) return [];

        return result;
    },

    // 6. Get Student Attendance Summary (percentage)
    async getStudentAttendanceSummary(studentId: string): Promise<number> {
        const { data } = await supabase
            .from('attendance')
            .select('status')
            .eq('student_id', studentId);

        if (!data || data.length === 0) return 100;

        const present = data.filter(a => a.status === 'hadir').length;
        return Math.round((present / data.length) * 100);
    },

    // 7. Get Rekap (for admin rekap page)
    async getRekap(filters: { date?: string; search?: string }): Promise<AttendanceRekapItem[]> {
        let query = supabase
            .from('attendance')
            .select(`
                id,
                date,
                status,
                notes,
                check_in_time,
                session,
                students (
                    id,
                    name,
                    nis,
                    class_id,
                    classes (name)
                )
            `)
            .order('date', { ascending: false });

        if (filters.date) {
            query = query.eq('date', filters.date);
        }

        const { data, error } = await query;

        if (error) {
            console.error('Error fetching rekap:', error);
            return [];
        }

        const result = (data || []).map((item: any): AttendanceRekapItem => ({
            id: item.id,
            studentId: item.students?.id,
            studentName: item.students?.name || 'Unknown',
