export const dormitoriesService = {
    async getAll(): Promise<DormitoryWithRelations[]> {
        const { data, error } = await supabase
            .from('dormitories')
            .select(`
                *,
                supervisor:profiles(id, name)
            `)
            .order('name');

        if (error) throw error;
        return data || [];
    },

    async getById(id: string): Promise<DormitoryWithRelations | null> {
        const { data, error } = await supabase
            .from('dormitories')
            .select(`
                *,
                supervisor:profiles(id, name)
            `)
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    async create(dorm: any): Promise<Dormitory> {
        const { requirePesantrenId } = await import('./helpers');
        const pesantrenId = await requirePesantrenId(dorm.pesantren_id);

        const { data, error } = await supabase
            .from('dormitories')
            .insert({
                name: dorm.name,
                building: dorm.building,
                capacity: dorm.capacity || 20,
                current_occupancy: dorm.current_occupancy || 0,
                supervisor_id: dorm.supervisor_id || null, // Handle empty string
                pesantren_id: pesantrenId
            })
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    async update(id: string, updates: any): Promise<Dormitory> {
        // Use RPC to bypass PostgREST cache issues (PGRST204)
        // This ensures the update works even if the API schema cache is stale
        const { data, error } = await supabase.rpc('update_dormitory_safe', {
            p_id: id,
            p_name: updates.name,
            p_building: updates.building,
            p_capacity: updates.capacity,
            p_supervisor_id: updates.supervisor_id || null
        });

        if (error) {
            console.error("RPC Update failed:", error);
            // Fallback to standard update if RPC doesn't exist (though it should)
            const cleanUpdates = {
                name: updates.name,
                building: updates.building, // This is the problematic column
                capacity: updates.capacity,
                supervisor_id: updates.supervisor_id || null,
            };

            const { data: standardData, error: standardError } = await supabase
                .from('dormitories')
                .update(cleanUpdates)
                .eq('id', id)
                .select()
                .single();

            if (standardError) throw standardError;
            return standardData;
        }

        // RPC returns the data directly (as JSONB, need to cast or wrap?)
        // The RPC returns just the JSON object of the row.
        return data as unknown as Dormitory;
    },

    async delete(id: string): Promise<void> {
        const { error } = await supabase
            .from('dormitories')
            .delete()
            .eq('id', id);

        if (error) throw error;
    },

    async getDensity(): Promise<any[]> {
        const dorms = await this.getAll();

        const colors = [
            '#8b5cf6', // Violet
            '#10b981', // Emerald
            '#3b82f6', // Blue
            '#f59e0b', // Amber
            '#f43f5e', // Rose
        ];

        return dorms.map((d, i) => ({
            name: d.name,
            value: d.current_occupancy,
            color: colors[i % colors.length]
        }));
    }
};

// Grades Service - CRUD operations for Nilai
import { supabase } from '../supabase';
import type { Grade, GradeInsert, GradeUpdate } from '@/types/database.types';

export interface GradeWithRelations extends Grade {
    student?: { id: string; name: string; nis: string } | null;
    subject?: { id: string; name: string; code: string } | null;
    teacher?: { id: string; name: string } | null;
}

export interface GradeFilters {
    studentId?: string;
    subjectId?: string;
    teacherId?: string;
    classId?: string;
    academicYearId?: string;
    semester?: 1 | 2;
}

export const gradesService = {
    /**
     * Get grades with filters
     */
    async getAll(filters?: GradeFilters): Promise<GradeWithRelations[]> {
        let query = supabase
            .from('grades')
            .select(`
                *,
                student:students(id, name, nis),
                subject:subjects(id, name, code),
                teacher:teachers(id, name)
            `);

        if (filters?.studentId) query = query.eq('student_id', filters.studentId);
        if (filters?.subjectId) query = query.eq('subject_id', filters.subjectId);
        if (filters?.teacherId) query = query.eq('teacher_id', filters.teacherId);
        if (filters?.academicYearId) query = query.eq('academic_year_id', filters.academicYearId);
        if (filters?.semester) query = query.eq('semester', filters.semester);

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    /**
     * Get grades by class (through students)
     */
    async getByClass(classId: string, subjectId?: string): Promise<GradeWithRelations[]> {
        let query = supabase
            .from('grades')
            .select(`
                *,
                student:students!inner(id, name, nis, class_id),
                subject:subjects(id, name, code)
            `)
            .eq('student.class_id', classId);

        if (subjectId) query = query.eq('subject_id', subjectId);

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    /**
     * Get student's grades
     */
    async getByStudent(studentId: string, semester?: 1 | 2): Promise<GradeWithRelations[]> {
        let query = supabase
            .from('grades')
            .select(`
                *,
                subject:subjects(id, name, code, category)
            `)
            .eq('student_id', studentId);

        if (semester) query = query.eq('semester', semester);

        const { data, error } = await query.order('created_at', { ascending: false });
        if (error) throw error;
        return data || [];
    },

    /**
     * Create or update grade (upsert)
     */
    async upsert(grade: GradeInsert): Promise<Grade> {
        const { data, error } = await supabase
            .from('grades')
            .upsert(grade, {
                onConflict: 'student_id,subject_id,academic_year_id,semester',
            })
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    /**
     * Bulk upsert grades
     */
    async bulkUpsert(grades: GradeInsert[]): Promise<Grade[]> {
        const { data, error } = await supabase
            .from('grades')
            .upsert(grades, {
                onConflict: 'student_id,subject_id,academic_year_id,semester',
            })
            .select();

        if (error) throw error;
        return data || [];
    },

    /**
     * Update specific grade fields
     */
    async update(id: string, updates: GradeUpdate): Promise<Grade> {
        // Calculate final grade if component grades are updated
        const finalGrade = this.calculateFinalGrade(updates);

        // Prepare updates with both possible field names for safety
        const gradeWithCalculation = finalGrade !== null
            ? {
                ...updates,
                final_grade: finalGrade,
                final_score: finalGrade, // Try to update both
                grade_letter: this.getGradeLetter(finalGrade)
            }
            : updates;

        const { data, error } = await supabase
            .from('grades')
            .update(gradeWithCalculation)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    /**
     * Delete grade
     */
    async delete(id: string): Promise<void> {
        const { error } = await supabase
            .from('grades')
            .delete()
            .eq('id', id);

        if (error) throw error;
    },

    /**
     * Calculate final grade from components
     */
    calculateFinalGrade(grade: Partial<Grade>): number | null {
        const { uh1, uh2, uts, uas } = grade;
        if (uh1 == null || uh2 == null || uts == null || uas == null) return null;
        // Typical formula: UH 25%, UTS 25%, UAS 50%
        return Math.round((Number(uh1) * 0.125 + Number(uh2) * 0.125 + Number(uts) * 0.25 + Number(uas) * 0.5) * 100) / 100;
    },

    /**
     * Get grade letter from numeric grade
     */
    getGradeLetter(grade: number): string {
        if (grade >= 90) return 'A';
        if (grade >= 80) return 'B';
        if (grade >= 70) return 'C';
        if (grade >= 60) return 'D';
        return 'E';
    },

    /**
     * Subscribe to grade changes for a class
     */
    subscribeToClassGrades(classId: string, callback: (payload: any) => void) {
        const channel = supabase
            .channel(`grades_class_${classId}`)
            .on('postgres_changes',
                { event: '*', schema: 'public', table: 'grades' },
                callback
            )
            .subscribe();

        return () => supabase.removeChannel(channel);
    },

    /**
     * Helper to get final grade value from potentially different column names
     */
    getFinalValue(grade: any): number {
        if (!grade) return 0;
        return Number(grade.final_grade ?? grade.final_score ?? 0);
    },
};

import { supabase } from '../supabase';

export const guardianService = {
    async getChildren(userId: string) {
        const { data, error } = await supabase
            .from('students')
            .select('*, classes(name)')
            .eq('parent_user_id', userId);

        if (error) throw error;
        return data || [];
    },

    async getHafalanGrowth(studentId: string) {
        // Try V2 first
        const { data: v2Data, error: v2Error } = await supabase
            .from('hafalan_progress')
            .select('created_at, unit_number')
            .eq('student_id', studentId)
            .order('created_at');

        if (!v2Error && v2Data && v2Data.length > 0) {
            const months: Record<string, number> = {};
            v2Data.forEach(h => {
                const month = new Date(h.created_at).toLocaleDateString('id-ID', { month: 'short' });
                months[month] = Math.max(months[month] || 0, h.unit_number);
            });

            return Object.entries(months).map(([month, unit]) => ({
                month,
                pages: unit // Mapping unit to pages for UI consistency
            }));
        }

        // Fallback to old table
        const { data: oldData } = await supabase
            .from('hafalan_progress_old')
            .select('created_at, end_ayat, start_ayat')
            .eq('student_id', studentId)
            .order('created_at');

        // Group by month
        const months: Record<string, number> = {};
        oldData?.forEach(h => {
            const month = new Date(h.created_at).toLocaleDateString('id-ID', { month: 'short' });
            const pages = Math.ceil(((h.end_ayat || 0) - (h.start_ayat || 0) + 1) / 15);
            months[month] = (months[month] || 0) + pages;
        });

        // Accumulative growth
        let total = 0;
        return Object.entries(months).map(([month, pages]) => {
            total += pages;
            return { month, pages: total };
        });
    },

    async getPotentialRadar(studentId: string) {
        const { data, error } = await supabase
            .from('grades')
            .select('final_grade, subjects(name)')
            .eq('student_id', studentId);

        if (error) throw error;

        // Map categories (simplification)
        const categories: Record<string, { total: number, count: number }> = {};
        data?.forEach((g: any) => {
            const name = g.subjects?.name || 'Unknown';
            const score = g.final_grade || 0;
            if (!categories[name]) categories[name] = { total: 0, count: 0 };
            categories[name].total += score;
            categories[name].count++;
        });

        return Object.entries(categories).map(([subject, stats]) => ({
            subject,
            A: Math.round(stats.total / stats.count),
            fullMark: 100
        })).slice(0, 6);
    },

    async getAttendanceHeatmap(studentId: string) {
        const today = new Date();
        const firstDayOfMonth = new Date(today.getFullYear(), today.getMonth(), 1).toISOString();

        const { data, error } = await supabase
            .from('attendance')
            .select('date, status')
            .eq('student_id', studentId)
            .gte('date', firstDayOfMonth);

        if (error) throw error;

        const daysInMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
        const heatmap = Array.from({ length: daysInMonth }, (_, i) => {
            const day = i + 1;
            const record = data?.find(d => new Date(d.date).getDate() === day);
            return {
                day,
                status: record?.status || 'none'
            };
        });

        return heatmap;
    }
};

