            .from('attendance')
            .select(`
                status,
                students!inner(class_id)
            `)
            .eq('date', today)
            .eq('students.class_id', classId);

        if (error) throw error;

        const summary = {
            'Hadir': 0,
            'Sakit': 0,
            'Izin': 0,
            'Alpha': 0,
