        // Group by pseudo-semesters
        const semesterGrades: Record<string, { total: number, count: number }> = {};
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (data || []).forEach((g: any, i: number) => {
            const sem = `Sem ${Math.floor(i / 5) + 1}`;
            if (!semesterGrades[sem]) semesterGrades[sem] = { total: 0, count: 0 };

            // Integrated Calculation Fallback
            // Support both final_score (MASTER-SETUP) and final_grade (V2/Legacy)
            let score = g.final_score ?? g.final_grade;

            if (score === null || score === undefined) {
                // Fallback to components if final score isn't calculated
                // Handle both short (uh1, uh2) and long (tugas_score, uts_score, uas_score) names
                const uh1 = g.uh1 ?? g.tugas_score ?? 0;
                const uh2 = g.uh2 ?? 0;
                const uts = g.uts ?? g.uts_score ?? 0;
                const uas = g.uas ?? g.uas_score ?? 0;

                const avgUh = (Number(uh1) + Number(uh2)) / (uh2 ? 2 : 1);
                score = (avgUh * 0.25) + (Number(uts) * 0.25) + (Number(uas) * 0.5);
            }

            semesterGrades[sem].total += Number(score);
            semesterGrades[sem].count += 1;
        });

        if (Object.keys(semesterGrades).length === 0) {
            return [
                { semester: 'Sem 1', gpa: 0 },
                { semester: 'Sem 2', gpa: 0 }
            ];
        }

        return Object.entries(semesterGrades).map(([semester, stats]) => ({
            semester,
            gpa: Number((stats.total / stats.count / 25).toFixed(2))
        })).slice(-5);
    },

    async getHafalanData(studentId: string) {
        // 1. Get Active Program first to get correct metadata
        const { data: activePrograms, error: progError } = await supabase
            .from('hafalan_programs')
            .select(`
                id,
                hafalan_types (
                    id,
                    name,
                    unit_name,
                    total_units
                )
            `)
            .eq('student_id', studentId)
            .eq('status', 'active')
            .limit(1);

        if (progError) throw progError;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const activeProg = activePrograms?.[0] as any;
        const metadata = activeProg?.hafalan_types;

        // 2. Get latest progress for this student
        const { data: v2Data, error: v2Error } = await supabase
            .from('hafalan_progress')
            .select(`
                unit_number,
                unit_name,
                progress_percentage,
                updated_at,
                hafalan_programs (
                    hafalan_types (
                        name,
                        unit_name,
                        total_units
                    )
                )
            `)
            .eq('student_id', studentId)
            .order('updated_at', { ascending: false });

        if (!v2Error && (v2Data && v2Data.length > 0)) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const latest = v2Data[0] as any;
            const progInfo = latest.hafalan_programs?.hafalan_types || metadata;
            const unitLabel = progInfo?.unit_name || 'Unit';
            const progName = progInfo?.name || 'Program';
            const totalTarget = progInfo?.total_units || 30;

            // Calculate completed units (progress_percentage = 100)
            const completedUnits = v2Data.filter(h => h.progress_percentage === 100).length;

            // Calculate total progress percentage across all units
            const totalSumProgress = v2Data.reduce((sum, h) => sum + (h.progress_percentage || 0), 0);
            const totalProgress = Math.min(100, Math.round(totalSumProgress / totalTarget));

            return {
                currentJuz: latest.unit_number,
                unitLabel: unitLabel,
                programName: progName,
                currentName: `${progName} - ${latest.unit_name || `${unitLabel} ${latest.unit_number}`}`,
                currentDetail: null,
                progress: latest.progress_percentage,
                totalProgress: totalProgress,
                completed: completedUnits,
                remaining: Math.max(0, totalTarget - completedUnits),
                totalTarget: totalTarget,
                lastUpdate: latest.updated_at,
                chartData: [
                    { name: 'Selesai', value: completedUnits },
                    { name: 'Target', value: Math.max(0, totalTarget - completedUnits) }
                ]
            };
        }

        // Try 'hafalan_progress_old' first if we suspect 'hafalan_progress' is already V2
        const { data: oldData, error: oldError } = await supabase
            .from('hafalan_progress_old')
            .select('*')
            .eq('student_id', studentId)
            .order('created_at', { ascending: false });

        if (!oldError && (oldData && oldData.length > 0)) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const latest = oldData[0] as any;
            const completedJuz = new Set(oldData.filter((h: any) =>
                ['completed', 'selesai', 'tuntas', 'lulus', 'muroja_ah', 'memorized'].includes(h.status?.toLowerCase())
            ).map((h: any) => h.juz)).size;
            const totalTarget = 30;

            return {
                currentJuz: latest.juz || 30,
                unitLabel: 'Juz',
                programName: 'Hafalan Qur\'an',
                currentName: `Juz ${latest.juz}`,
                currentDetail: latest.surah || '-',
                progress: 100,
                totalProgress: Number(((completedJuz / totalTarget) * 100).toFixed(0)),
                completed: completedJuz,
                remaining: totalTarget - completedJuz,
                totalTarget: totalTarget,
                lastUpdate: latest.created_at,
                chartData: [
                    { name: 'Completed', value: completedJuz },
                    { name: 'Remaining', value: totalTarget - completedJuz }
                ]
            };
        }

        // 3. Fallback: If no progress yet but has active program
        if (activeProg) {
            const unitLabel = metadata.unit_name || 'Unit';
            const progName = metadata.name || 'Program';
            const totalTarget = metadata.total_units || 30;

            return {
                currentJuz: 1,
                unitLabel: unitLabel,
                programName: progName,
                currentName: `${progName} - ${unitLabel} 1`,
                currentDetail: null,
                progress: 0,
                totalProgress: 0,
                completed: 0,
                remaining: totalTarget,
                totalTarget: totalTarget,
                lastUpdate: null,
                chartData: [
                    { name: 'Selesai', value: 0 },
                    { name: 'Target', value: totalTarget }
                ]
            };
        }

        // 2. Fallback to legacy schema (if hafalan_progress_old didn't exist or was empty)
        const tryLegacy = async (tableName: string) => {
            // Check only what we need, with safer selection
            const { data, error } = await supabase
                .from(tableName)
                .select('*') // Safer than listing missing columns
                .eq('student_id', studentId);

            if (error) return { data: [], error };

            // Re-apply ordering in JS to be safe
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const sorted = (data || []).sort((a: any, b: any) => (b.juz || 0) - (a.juz || 0));
            return { data: sorted, error: null };
        };

        let legacyData: any[] = [];
        // If old table doesn't exist/empty, maybe the main table IS legacy
        const mainResult = await tryLegacy('hafalan_progress');
        if (mainResult.data?.[0]?.juz !== undefined) {
            legacyData = mainResult.data;
        }


        const latest = legacyData[0];
        if (!latest) return null; // Return null if absolutely no data found

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const completedJuz = new Set(legacyData.filter((h: any) =>
            ['completed', 'selesai', 'tuntas', 'lulus', 'muroja_ah', 'memorized'].includes(h.status?.toLowerCase())
        ).map((h: any) => h.juz)).size;

        const totalTarget = 30;

        return {
            currentJuz: latest.juz,
            unitLabel: 'Juz',
            programName: 'Hafalan Al-Qur\'an',
            currentName: latest.surah_name ? `Surah ${latest.surah_name}` : `Juz ${latest.juz}`,
            currentDetail: latest ? `Ayat ${latest.start_ayat || 1} - ${latest.end_ayat || '...'}` : null,
            progress: 0,
            totalProgress: Math.round((completedJuz / totalTarget) * 100),
            completed: completedJuz,
            remaining: Math.max(0, totalTarget - completedJuz),
            totalTarget: totalTarget,
            lastUpdate: latest.updated_at,
            chartData: [
                { name: 'Selesai', value: completedJuz },
                { name: 'Target', value: Math.max(0, totalTarget - completedJuz) }
            ]
        };
    },

    async getTodaySchedule(studentId: string) {
        const { data: student, error: sError } = await supabase
            .from('students')
            .select('class_id')
            .eq('id', studentId)
            .maybeSingle();

        if (sError) throw sError;
        if (!student?.class_id) return [];

        const todayIdx = new Date().getDay();

        const { data, error } = await supabase
            .from('schedules')
            .select(`
                id,
                start_time,
                end_time,
                room,
                subjects (name),
                teachers (
                    name
                )
            `)
            .eq('class_id', student.class_id)
            .eq('day_of_week', todayIdx)
            .order('start_time');

        if (error) throw error;

        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:00`;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return (data || []).map((s: any) => ({
            id: s.id,
            time: `${s.start_time.slice(0, 5)} - ${s.end_time.slice(0, 5)}`,
            subject: s.subjects?.name || 'Unknown',
            teacher: s.teachers?.name || 'Ustadz/Teacher',
            room: s.room || 'N/A',
            status: currentTime > s.end_time ? 'Selesai' : currentTime < s.start_time ? 'Akan Datang' : 'Sedang Berlangsung'
        }));
    },

    async getTopScore(studentId: string) {
        try {
            const { data, error } = await supabase
                .from('grades')
                .select(`
                    final_score,
                    final_grade,
                    uas_score,
                    uas,
                    subjects (name)
                `)
                .eq('student_id', studentId)
                .order('final_grade', { ascending: false })
                .limit(1)
                .maybeSingle();

            if (error) throw error;
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            return data as any;
        } catch (err) {
            console.error('Error in getTopScore:', err);
            return null;
        }
    },

    async getDisciplinePoints(studentId: string) {
        const { data, error } = await supabase
            .from('violations')
            .select('points')
            .eq('student_id', studentId);

        if (error) {
            // Try legacy table?
            const { data: legacy, error: lErr } = await supabase.from('students').select('total_violation_points').eq('id', studentId).single();
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            if (!lErr && legacy) return 100 - ((legacy as any).total_violation_points || 0);

            return 100;
        }

        // Base points is 100, deducted by violations
        const totalViolations = (data || []).reduce((acc, curr) => acc + (curr.points || 0), 0);
        return Math.max(0, 100 - totalViolations);
    },

    async getRecentViolations(studentId: string) {
        const { data, error } = await supabase
            .from('violations')
            .select(`
                id,
                created_at,
                description,
                points,
                punishment,
                status
            `)
            .eq('student_id', studentId)
            .order('created_at', { ascending: false })
            .limit(3);

        if (error) return [];
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return (data || []).map((v: any) => ({
            id: v.id,
            created_at: v.created_at,
            description: v.description,
            points: v.points,
            punishment: v.punishment,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            status: v.status as any
        }));
    },

    async getWeeklySchedule(studentId: string) {
        const { data: student, error: sError } = await supabase
            .from('students')
            .select('class_id')
            .eq('id', studentId)
            .single();

        if (sError) throw sError;

        const { data, error } = await supabase
            .from('schedules')
            .select(`
                id,
                day_of_week,
                start_time,
                end_time,
                room,
                subjects (name),
                teachers (name)
            `)
            .eq('class_id', student?.class_id)
            .order('day_of_week')
            .order('start_time');

        if (error) throw error;
        return data || [];
    }
};

// Students Service - CRUD operations for Santri
import { supabase } from '../supabase';
import type { Student, StudentInsert, StudentUpdate } from '@/types/database.types';

export interface StudentWithRelations extends Student {
    class?: { id: string; name: string } | null;
    dormitory?: { id: string; name: string } | null;
}

export interface StudentFilters {
    classId?: string;
    dormitoryId?: string;
    status?: 'active' | 'graduated' | 'dropped';
    search?: string;
}

export const studentsService = {
    /**
     * Get all students with optional filters
     */
    async getAll(filters?: StudentFilters): Promise<StudentWithRelations[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('students')
            .select(`
                *,
                class:classes(id, name),
                dormitory:dormitories(id, name)
            `)
            .order('name');

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }
        if (filters?.classId) {
            query = query.eq('class_id', filters.classId);
        }
        if (filters?.dormitoryId) {
            query = query.eq('dormitory_id', filters.dormitoryId);
        }
        if (filters?.status) {
            query = query.eq('status', filters.status);
        }
        if (filters?.search) {
            query = query.or(`name.ilike.%${filters.search}%,nis.ilike.%${filters.search}%`);
        }

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    /**
     * Get student by ID with full relations
     */
    async getById(id: string): Promise<StudentWithRelations | null> {
        const { data, error } = await supabase
            .from('students')
            .select(`
                *,
                class:classes(*),
                dormitory:dormitories(*)
            `)
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null; // Not found
            throw error;
        }
        return data;
    },

    /**
     * Get students by class
     */
    async getByClass(classId: string): Promise<StudentWithRelations[]> {
        const { data, error } = await supabase
            .from('students')
            .select(`
                *,
                class:classes(id, name),
                dormitory:dormitories(id, name)
            `)
            .eq('class_id', classId)
            .eq('status', 'active')
            .order('name');

        if (error) throw error;
        return data || [];
    },

    /**
     * Create new student (with automatic user account for santri and optionally parent)
     */
    async create(student: StudentInsert): Promise<Student> {
        try {
            const { requirePesantrenId } = await import('./helpers');
            const pesantrenId = await requirePesantrenId((student as any).pesantren_id);

            // Call API route that uses Supabase Auth Admin API
            const response = await fetch('/api/admin/create-student', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    ...student,
                    pesantren_id: pesantrenId
                })
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.error || 'Failed to create student');
            }
            return data as unknown as Student;
        } catch (err: unknown) {
            console.error('Error in studentsService.create:', err);
            throw err;
        }
    },

    /**
     * Update student
     */
    async update(id: string, student: StudentUpdate): Promise<Student> {
        const { data, error } = await supabase
            .from('students')
            .update(student)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    /**
     * Delete student and associated auth user
     */
    async delete(id: string): Promise<void> {
        // Try cascade delete first (removes auth user too)
        const { data, error: rpcError } = await supabase.rpc('delete_student_cascade', {
            p_student_id: id
        });

        if (rpcError) {
            console.warn('RPC delete failed, falling back to direct delete:', rpcError);
            // Fallback to direct delete (won't remove auth user)
            const { error } = await supabase
                .from('students')
                .delete()
                .eq('id', id);

            if (error) throw error;
            return;
        }

        if (data && !data.success) {
            throw new Error(data.message || 'Gagal menghapus santri');
        }
    },

    /**
     * Bulk import students
     */
    async bulkImport(students: StudentInsert[]): Promise<Student[]> {
        const { data, error } = await supabase
            .from('students')
            .insert(students)
            .select();

        if (error) throw error;
        return data || [];
    },

    /**
     * Get student count by status
     */
    async getStats(): Promise<{ active: number; graduated: number; dropped: number; total: number }> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        const getCount = async (status: string) => {
            let query = supabase
                .from('students')
                .select('*', { count: 'exact', head: true })
                .eq('status', status);

            if (pesantrenId) {
                query = query.eq('pesantren_id', pesantrenId);
            }
            return query;
        };

        const [active, graduated, dropped] = await Promise.all([
            getCount('active'),
            getCount('graduated'),
            getCount('dropped')
        ]);

        return {
            active: active.count || 0,
            graduated: graduated.count || 0,
            dropped: dropped.count || 0,
            total: (active.count || 0) + (graduated.count || 0) + (dropped.count || 0),
        };
    },

    async getGenderRatio(): Promise<any[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase.from('students').select('gender');
        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;

        if (error) throw error;

        const counts = { L: 0, P: 0 };
        data?.forEach(s => {
            if (s.gender === 'L') counts.L++;
            if (s.gender === 'P') counts.P++;
        });

        if (counts.L === 0 && counts.P === 0) return [];

        return [
            { name: 'Santri Putra', value: counts.L, color: '#10b981' },
            { name: 'Santri Putri', value: counts.P, color: '#f43f5e' },
        ];
    },

    /**
     * Subscribe to real-time student changes
     */
    subscribeToChanges(callback: (payload: any) => void) {
        const channel = supabase
            .channel('students_changes')
            .on('postgres_changes',
                { event: '*', schema: 'public', table: 'students' },
                callback
            )
            .subscribe();

        return () => supabase.removeChannel(channel);
    },
};

