        if (updates.hours_per_week !== undefined) payload.hours_per_week = updates.hours_per_week;
        if (updates.category) payload.category = updates.category.toLowerCase();

        const { data, error } = await supabase
            .from('subjects')
            .update(payload)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
