        }

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    /**
     * Get teacher by ID
     */
    async getById(id: string): Promise<Teacher | null> {
        const { data, error } = await supabase
            .from('teachers')
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    /**
     * Get teacher by user ID (for ustadz login)
     */
    async getByUserId(userId: string): Promise<Teacher | null> {
        const { data, error } = await supabase
            .from('teachers')
            .select('*')
            .eq('user_id', userId)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    /**
     * Create new teacher (with automatic user account)
     */
    async create(teacher: TeacherInsert): Promise<Teacher> {
        try {
            const { requirePesantrenId } = await import('./helpers');
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const pesantrenId = await requirePesantrenId((teacher as any).pesantren_id);

            // Call API route that uses Supabase Auth Admin API
            const response = await fetch('/api/admin/create-teacher', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    ...teacher,
                    pesantren_id: pesantrenId
                })
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.error || 'Failed to create teacher');
            }

            return data as unknown as Teacher;
        } catch (error: unknown) {
            console.error('Create teacher error:', error);
            throw error;
        }
    },

    /**
     * Update teacher
     */
    async update(id: string, updates: TeacherUpdate): Promise<Teacher> {
        const { data, error } = await supabase
            .from('teachers')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    /**
     * Delete teacher and associated auth user
     */
    async delete(id: string): Promise<void> {
        // Try cascade delete first (removes auth user too)
        const { data, error: rpcError } = await supabase.rpc('delete_teacher_cascade', {
            p_teacher_id: id
        });

        if (rpcError) {
            console.warn('RPC delete failed, falling back to direct delete:', rpcError);
            // Fallback to direct delete (won't remove auth user)
            const { error } = await supabase
                .from('teachers')
                .delete()
                .eq('id', id);

            if (error) throw error;
            return;
        }

        if (data && !data.success) {
            throw new Error(data.message || 'Gagal menghapus guru');
        }
    },

    /**
     * Get active teacher count
     */
    async getActiveCount(): Promise<number> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('teachers')
            .select('*', { count: 'exact', head: true })
            .eq('is_active', true);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { count, error } = await query;

        if (error) throw error;
        return count || 0;
    },

    /**
     * Get unique specializations
     */
    async getSpecializations(): Promise<string[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('teachers')
            .select('specialization')
            .not('specialization', 'is', null);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;

        if (error) throw error;
        const specs = new Set(data?.map(t => t.specialization).filter(Boolean));
        return Array.from(specs) as string[];
    },

    async getLoad(): Promise<{ name: string; hours: number }[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('schedules')
            .select(`
                teacher_id,
                teachers(name)
            `);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;

        const loads: Record<string, { name: string, hours: number }> = {};
        data?.forEach((s: any) => {
            const teacherObj = Array.isArray(s.teachers) ? s.teachers[0] : s.teachers;
            if (s.teacher_id && teacherObj) {
                if (!loads[s.teacher_id]) {
                    loads[s.teacher_id] = { name: teacherObj.name, hours: 0 };
                }
                loads[s.teacher_id].hours += 2;
            }
        });

        return Object.values(loads).sort((a, b) => b.hours - a.hours).slice(0, 5);
    },
};

// Users Service - Admin user management
import { supabase } from '../supabase';
import type { Profile, ProfileUpdate } from '@/types/database.types';
import { createUser, UserRole } from '../auth';

export interface UserWithDetails extends Profile {
    last_login?: string;
}

export interface UserFilters {
    role?: UserRole | 'all';
    isActive?: boolean;
    search?: string;
    pesantrenId?: string | 'all';
}

export interface SystemHealthItem {
    name: string;
    status: 'healthy' | 'warning' | 'error';
    value: string;
    icon: string;
}

export interface LoginTrafficItem {
    date: string;
    value: number;
}

export const usersService = {
    async getAll(filters?: UserFilters): Promise<Profile[]> {
        // 1. Get user from local storage cache
        const cachedUser = typeof window !== 'undefined' ? localStorage.getItem('smart_pesantren_user') : null;
        const currentUser = cachedUser ? JSON.parse(cachedUser) : null;

        const isSuperAdmin = currentUser?.role === 'super_admin';

        // 2. Prepare optimized query
        let query = supabase
            .from('profiles')
            .select('*')
            .order('created_at', { ascending: false });

        // 3. Fast Filtering
        // ONLY restrict if NOT super_admin
        if (!isSuperAdmin && currentUser?.pesantrenId) {
            query = query.eq('pesantren_id', currentUser.pesantrenId);
        }

        // Apply additional filters
        if (filters?.isActive !== undefined) {
            query = query.eq('is_active', filters.isActive);
        }

        if (filters?.role && filters.role !== 'all') {
            query = query.eq('role', filters.role);
        }

        if (filters?.search) {
            query = query.or(`name.ilike.%${filters.search}%,email.ilike.%${filters.search}%`);
        }

        // Apply Pesantren Filter from UI (if Super Admin is filtering by a specific pesantren)
        if (isSuperAdmin && filters?.pesantrenId && filters.pesantrenId !== 'all') {
            query = query.eq('pesantren_id', filters.pesantrenId);
        }

        const { data, error } = await query;
        if (error) {
            console.error('Fetch Error:', error);
            throw error;
        }

        return data || [];
    },

    async getById(id: string): Promise<Profile | null> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    async getByRole(role: UserRole): Promise<Profile[]> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('role', role)
            .order('name');

        if (error) throw error;
        return data || [];
    },

    async getPotentialSupervisors(): Promise<Profile[]> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .in('role', ['ustadz', 'musyrif', 'kesantrian', 'super_admin'])
            .order('name');

        if (error) throw error;
        return data || [];
    },

    async create(
        email: string,
        password: string,
        name: string,
        role: UserRole,
        phone?: string,
        pesantrenId?: string
    ): Promise<{ success: boolean; user?: Profile; error?: string }> {
        try {
            // Call API route that uses Supabase Auth Admin API (SAFE & PRODUCTION-READY)
            const response = await fetch('/api/admin/create-user', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email,
                    password,
                    name,
                    role,
                    phone,
                    pesantren_id: pesantrenId
                })
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                return { success: false, error: data.error || 'Failed to create user' };
            }

            // Fetch the created profile to return it
            if (data.user_id) {
                const profile = await this.getById(data.user_id);
                return { success: true, user: profile || undefined };
            }

            return { success: true };
        } catch (error: unknown) {
            console.error('Create user error:', error);
            const message = error instanceof Error ? error.message : 'Network error';
            return { success: false, error: message };
        }
    },

    async update(id: string, updates: ProfileUpdate): Promise<Profile> {
        const { data, error } = await supabase
            .from('profiles')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    async toggleActive(id: string): Promise<Profile> {
        const current = await this.getById(id);
        if (!current) throw new Error('User not found');

        return this.update(id, { is_active: !current.is_active });
    },

    async updateRole(userId: string, newRole: UserRole): Promise<void> {
        // 1. Update profiles table (if column exists)
        await supabase
            .from('profiles')
            .update({ role: newRole })
            .eq('id', userId);

        // 2. Update user_roles table
        // Delete existing roles first to maintain single primary role for this simplified management
        await supabase
            .from('user_roles')
            .delete()
            .eq('user_id', userId);

        const { error } = await supabase
            .from('user_roles')
            .insert({
                user_id: userId,
                role: newRole
            });

        if (error) throw error;
    },

    async delete(id: string): Promise<void> {
        // Use the secure RPC function to delete from both auth.users and public.profiles
        const { error } = await supabase.rpc('delete_user_complete', {
            target_user_id: id
        });

        if (error) {
            console.error('RPC delete_user_complete failed:', error.message, error.details);

            // Fallback: Try hard delete from profiles directly (handling Ghost User case)
            const { error: deleteError } = await supabase
                .from('profiles')
                .delete()
                .eq('id', id);

            if (deleteError) {
                // Check for Foreign Key Constraint violation
                if (deleteError.code === '23503') {
                    throw new Error('Gagal menghapus user: User ini terhubung dengan data lain (misal: mengajar kelas, ada nilai, dll). Hapus data terkait terlebih dahulu.');
                }
                console.error('Direct profile delete failed:', deleteError);
                throw new Error(deleteError.message);
            }
        }
    },

    async getStats(): Promise<{ total: number; active: number; byRole: Record<string, number> }> {
        // High Speed Fetch: Use combined RPC to get all stats in one trip
        const { data, error } = await supabase.rpc('get_super_admin_stats');

        if (error) {
            console.error('Failed to fetch user stats via RPC:', error);
            return { total: 0, active: 0, byRole: {} };
        }

        return {
            total: data.total_users || 0,
            active: data.active_users || 0,
            byRole: {}
        };
    },

    async getSystemHealth(): Promise<SystemHealthItem[]> {
        // Mock health but with real DB check
        const start = Date.now();
        const { error } = await supabase.from('profiles').select('id', { count: 'exact', head: true });
        const latency = Date.now() - start;

        return [
            { name: 'Server Status', status: 'healthy', value: 'Online', icon: 'server' },
            { name: 'Database', status: error ? 'error' : 'healthy', value: error ? 'Disconnected' : 'Connected', icon: 'database' },
            { name: 'Latency', status: latency < 500 ? 'healthy' : 'warning', value: `${latency}ms`, icon: 'wifi' },
            { name: 'Storage', status: 'healthy', value: 'Optimized', icon: 'hard-drive' },
            { name: 'Security', status: 'healthy', value: 'SSL Active', icon: 'shield' },
            { name: 'Backups', status: 'healthy', value: 'Daily Active', icon: 'clock' },
        ];
    },

    async getLoginTraffic(): Promise<LoginTrafficItem[]> {
        const { data, error } = await supabase
            .from('login_logs')
            .select('login_time')
            .gte('login_time', new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString())
            .order('login_time');

        if (error) throw error;

        // Group by day
        const days: Record<string, number> = {};
        // Initialize last 7 days
        for (let i = 6; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const dateStr = d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
            days[dateStr] = 0;
        }

        data?.forEach(log => {
            const dateStr = new Date(log.login_time).toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
            if (days[dateStr] !== undefined) days[dateStr]++;
        });

        return Object.entries(days).map(([date, value]) => ({ date, value }));
    },

    subscribeToChanges(callback: (payload: { [key: string]: any }) => void) {
        const channel = supabase
            .channel('profiles_changes')
            .on('postgres_changes',
                { event: '*', schema: 'public', table: 'profiles' },
                callback
            )
            .subscribe();
        return () => supabase.removeChannel(channel);
    },
};

import { supabase } from '../supabase';

export const ustadzService = {
    /**
     * Helper to get teacher record ID from user ID
     */
    async getTeacherId(userId: string) {
        if (!userId) return null;

        try {
            // 1. Try to get existing teacher record
            const { data, error } = await supabase
                .from('teachers')
                .select('id')
                .eq('user_id', userId)
                .maybeSingle();

            // 2. Auto-repair/sync: If user is ustadz but record missing in teachers table
            if (!data && !error) {
                console.log('Teacher record missing. Attempting auto-reconcile for userId:', userId);
                const { data: profile } = await supabase.from('profiles').select('*').eq('id', userId).single();

                if (profile && (profile.role === 'ustadz' || profile.role === 'wali_kelas')) {
                    const { data: newTeacher, error: createError } = await supabase
                        .from('teachers')
                        .insert([{
                            user_id: userId,
                            name: profile.name,
                            email: profile.email,
                            is_active: true,
                            pesantren_id: profile.pesantren_id,
                            status: 'active'
                        }])
                        .select()
                        .single();

                    if (!createError) return newTeacher.id;
                    console.error('Reconcile failed:', createError);
                }
            }

            if (error) {
                console.error('Supabase error in getTeacherId:', error);
                return null;
            }

            return data?.id || null;
        } catch (err) {
            console.error('Unexpected error in getTeacherId:', err);
            return null;
        }
    },

    async getGradeDistribution(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) {
                console.warn('getGradeDistribution: No teacher record found for', userId);
                return [];
            }

            const { data, error } = await supabase
                .from('grades')
                .select('grade_letter')
                .eq('teacher_id', teacherId);

            if (error) throw error;

            const distribution: Record<string, number> = {
                'A': 0, 'B': 0, 'C': 0, 'D': 0, 'E': 0
            };

            const colors: Record<string, string> = {
                'A': '#8b5cf6', 'B': '#a78bfa', 'C': '#c4b5fd', 'D': '#ddd6fe', 'E': '#ede9fe'
            };

            data?.forEach(g => {
                const grade = g.grade_letter || 'C';
                if (distribution[grade] !== undefined) distribution[grade]++;
            });

            return Object.entries(distribution).map(([grade, count]) => ({
                grade,
                count,
                color: colors[grade]
            }));
        } catch (err) {
            console.error('Error in getGradeDistribution:', err);
            return [];
        }
    },

    async getHafalanProgress(userId: string) {
        try {
            // STRATEGY: 
            // 1. Try V2 Schema (New): Hafalan records use evaluated_by (User ID)
            const { data: v2Data, error: v2Error } = await supabase
                .from('hafalan_progress')
                .select('created_at, unit_number')
                .eq('evaluated_by', userId)
                .gte('created_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString());

            // If V2 call succeeded and found data, use it
            if (!v2Error && v2Data && v2Data.length > 0) {
                const weeks: Record<string, { total: number, count: number }> = {
                    'Minggu 1': { total: 0, count: 0 },
                    'Minggu 2': { total: 0, count: 0 },
                    'Minggu 3': { total: 0, count: 0 },
                    'Minggu 4': { total: 0, count: 0 },
                };

                const now = new Date();
                v2Data.forEach(h => {
                    const date = new Date(h.created_at);
                    const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));
                    let weekKey = '';
                    if (diffDays <= 7) weekKey = 'Minggu 4';
                    else if (diffDays <= 14) weekKey = 'Minggu 3';
                    else if (diffDays <= 21) weekKey = 'Minggu 2';
                    else if (diffDays <= 30) weekKey = 'Minggu 1';

                    if (weekKey) {
                        weeks[weekKey].total += 1;
                        weeks[weekKey].count += 1;
                    }
                });

                return Object.entries(weeks).map(([week, stats]) => ({
                    week,
                    average: stats.total
                }));
            }

            // 2. Fallback to V2 Schema but check if data exists
            // Since the main table no longer has teacher_id, we should NEVER query it there.
            // If we want legacy data, we check hafalan_progress_old
            const { data: oldData, error: oldError } = await supabase
                .from('hafalan_progress_old')
                .select('created_at')
                .eq('teacher_id', await this.getTeacherId(userId));

            if (oldError || !oldData || oldData.length === 0) {
                return [];
            }

            const weeks: Record<string, { total: number, count: number }> = {
                'Minggu 1': { total: 0, count: 0 },
                'Minggu 2': { total: 0, count: 0 },
                'Minggu 3': { total: 0, count: 0 },
                'Minggu 4': { total: 0, count: 0 },
            };

            const now = new Date();
            oldData.forEach(h => {
                const date = new Date(h.created_at);
                const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));

                let weekKey = '';
                if (diffDays <= 7) weekKey = 'Minggu 4';
                else if (diffDays <= 14) weekKey = 'Minggu 3';
                else if (diffDays <= 21) weekKey = 'Minggu 2';
                else if (diffDays <= 30) weekKey = 'Minggu 1';

                if (weekKey) {
                    weeks[weekKey].total += 1;
                    weeks[weekKey].count += 1;
                }
            });

            return Object.entries(weeks).map(([week, stats]) => ({
                week,
                average: stats.total
            }));
        } catch (err) {
            console.error('Error in getHafalanProgress:', err);
            return [];
        }
    },

